    zero_coupling_panel = w.GridBox([
        all_to_zero,
        w.HBox(subsystem_buttons),
        w.GridBox(
            np.reshape(resonance_buttons, (4, 3)).T.flatten().tolist(),
            layout=w.Layout(grid_template_columns=4 * "auto "),
        ),
    ])

    def get_subscript(p):
        return Rf"{p.latex} \to K^- p" if "1405" in p.name else p.latex

    grouped_sliders = []
